-- SAVE operation for packages
CREATE OR REPLACE FUNCTION save_packages(
  p_data JSONB,
  p_user_id INT
) RETURNS JSONB AS $$
DECLARE
  v_result packages%ROWTYPE;
  v_existing packages%ROWTYPE;
  v_is_insert BOOLEAN := false;
  v_notify_users INT[];
